import java.util.*;

class Solution {
  public int minimumObstacles(int[][] grid) {
    int m = grid.length, n = grid[0].length;
    int[][] d = new int[m][n];
    for (int[] x : d) Arrays.fill(x, Integer.MAX_VALUE);
    Deque<int[]> q = new ArrayDeque<>();
    d[0][0] = 0;
    q.add(new int[] {0, 0});
    int[][] ds = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!q.isEmpty()) {
      int[] u = q.poll();
      int r = u[0], c = u[1];
      for (int[] z : ds) {
        int x = r + z[0], y = c + z[1];
        if (x >= 0 && x < m && y >= 0 && y < n && d[x][y] > d[r][c] + grid[x][y]) {
          d[x][y] = d[r][c] + grid[x][y];
          if (grid[x][y] == 0) q.addFirst(new int[] {x, y});
          else q.addLast(new int[] {x, y});
        }
      }
    }
    return d[m - 1][n - 1];
  }
}
